package com.portfolio.urlshortener.service;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.portfolio.urlshortener.dto.UrlDtos.CreateUrlRequest;import com.portfolio.urlshortener.entity.AppUser;import com.portfolio.urlshortener.exception.ApiException;import com.portfolio.urlshortener.repository.*;import org.springframework.core.env.Environment;import static org.mockito.Mockito.*;
class UrlValidationTest {@Test void rejectsJavascriptAndUserInfoUrls(){var repo=mock(ShortenedUrlRepository.class);var users=mock(UserRepository.class);var clicks=mock(ClickEventRepository.class);var cache=mock(UrlCacheService.class);var env=mock(Environment.class);when(env.getProperty("app.base-url","http://localhost:8080")).thenReturn("http://localhost:8080");var svc=new UrlService(repo,users,clicks,new ShortCodeGenerator(),cache,env);when(users.findByEmail("x@example.com")).thenReturn(java.util.Optional.of(new AppUser("x@example.com","hash")));assertThrows(ApiException.class,()->svc.create("x@example.com",new CreateUrlRequest("javascript:alert(1)",null,null)));assertThrows(ApiException.class,()->svc.create("x@example.com",new CreateUrlRequest("https://user:pass@example.com",null,null)));}}
